INSERT INTO places (id,province_id,submitted_by,name,slug,category_id,address,short_description,description,cover_image,price_info,opening_hours,status,is_featured,approved_at) VALUES
(1,3,1,'Vịnh Hạ Long','vinh-ha-long',2,'Thành phố Hạ Long, Quảng Ninh','Kỳ quan thiên nhiên với hàng nghìn đảo đá vôi giữa làn nước xanh ngọc.','Vịnh Hạ Long mở ra một thế giới của núi đá, hang động và những làng chài bình yên. Hành trình đẹp nhất thường bắt đầu từ bến tàu vào sáng sớm, khi lớp sương mỏng còn phủ trên mặt vịnh.\n\nDu khách có thể chọn chuyến tham quan trong ngày hoặc ngủ đêm trên vịnh để ngắm hoàng hôn, chèo kayak và khám phá hang động.','https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=1400&q=85','290.000đ – 1.200.000đ','06:00 – 18:00','approved',1,NOW()),
(2,4,1,'Quần thể Tràng An','trang-an-ninh-binh',4,'Hoa Lư, Ninh Bình','Hành trình thuyền nan len giữa núi đá vôi, hang xuyên thủy và đền cổ.','Tràng An gây ấn tượng bằng những dòng sông trong xanh uốn quanh chân núi. Mỗi tuyến thuyền đưa du khách qua hệ thống hang động và điểm tâm linh khác nhau.\n\nNên đến vào buổi sáng, chuẩn bị mũ và nước uống, đồng thời giữ yên lặng khi qua các khu vực đền thờ.','https://images.unsplash.com/photo-1521993117367-b7f70ccd029d?auto=format&fit=crop&w=1400&q=85','250.000đ/người','07:00 – 16:30','approved',1,NOW()),
(3,5,1,'Đỉnh Fansipan','dinh-fansipan',3,'Sa Pa, Lào Cai','Chạm tay vào nóc nhà Đông Dương giữa biển mây Tây Bắc.','Fansipan cao 3.143 mét, là biểu tượng của những chuyến đi chinh phục miền núi phía Bắc. Du khách có thể trekking nhiều ngày hoặc sử dụng cáp treo.\n\nThời tiết thay đổi nhanh nên hãy mang áo ấm, giày chống trượt và kiểm tra dự báo trước khi khởi hành.','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=85','Theo dịch vụ cáp treo','07:30 – 17:30','approved',1,NOW()),
(4,21,1,'Phố cổ Hội An','pho-co-hoi-an',1,'Phường Hội An, Đà Nẵng','Những mái ngói rêu phong, đèn lồng và nhịp sống chậm bên sông Hoài.','Hội An đẹp vào mọi thời điểm trong ngày. Buổi sáng bình dị với những quán nhỏ mở cửa sớm; chiều vàng ươm trên các bức tường cổ; đêm đến phố bừng sáng trong sắc đèn lồng.\n\nHãy dành thời gian đi bộ, ghé các hội quán, thưởng thức cao lầu và quan sát đời sống bên sông.','https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?auto=format&fit=crop&w=1400&q=85','120.000đ/vé tham quan','Cả ngày','approved',1,NOW()),
(5,21,1,'Cầu Vàng Bà Nà Hills','cau-vang-ba-na-hills',5,'Hòa Vang, Đà Nẵng','Cây cầu giữa mây được nâng đỡ bởi đôi bàn tay đá khổng lồ.','Cầu Vàng nằm trong quần thể Bà Nà Hills, nổi bật với tầm nhìn bao quát núi rừng. Thời điểm ít đông thường là đầu giờ sáng.\n\nKhu vực trên cao có thể lạnh và nhiều sương kể cả mùa hè, vì vậy một chiếc áo khoác nhẹ sẽ hữu ích.','https://images.unsplash.com/photo-1584003564911-a7a321c84e1c?auto=format&fit=crop&w=1400&q=85','Theo vé khu du lịch','08:00 – 22:00','approved',0,NOW()),
(6,20,1,'Đại Nội Huế','dai-noi-hue',1,'Phú Hậu, Huế','Không gian cung đình trầm mặc lưu giữ dấu ấn triều Nguyễn.','Đại Nội là trái tim của quần thể di tích cố đô Huế. Những cổng thành, sân điện và hành lang đỏ kể lại nhiều lớp lịch sử.\n\nDu khách nên dành ít nhất nửa ngày, mặc trang phục lịch sự và mang theo nước uống vào mùa nắng.','https://images.unsplash.com/photo-1570366583862-f91883984fde?auto=format&fit=crop&w=1400&q=85','200.000đ/người lớn','06:30 – 17:30','approved',1,NOW()),
(7,25,1,'Vịnh Nha Trang','vinh-nha-trang',2,'Nha Trang, Khánh Hòa','Vịnh biển trong xanh với nhiều hòn đảo và hoạt động dưới nước.','Nha Trang kết hợp thuận tiện giữa nghỉ dưỡng đô thị và khám phá biển đảo. Một ngày trên vịnh có thể gồm lặn ngắm san hô, tắm biển và ghé làng chài.\n\nNên chọn đơn vị vận hành uy tín, tuân thủ hướng dẫn an toàn và không chạm vào san hô.','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1400&q=85','Tùy tour','Cả ngày','approved',0,NOW()),
(8,32,1,'Đảo Phú Quốc','dao-phu-quoc',2,'Phú Quốc, An Giang','Đảo ngọc với bãi cát dài, rừng xanh và hoàng hôn rực rỡ.','Phú Quốc có đủ trải nghiệm từ nghỉ dưỡng, khám phá rừng đến những chuyến đi canô qua các đảo nhỏ. Bờ tây là nơi ngắm hoàng hôn đẹp, trong khi phía bắc còn nhiều mảng xanh.\n\nMùa khô thuận lợi cho hoạt động biển; mùa mưa lại yên tĩnh và có mức chi phí dễ chịu hơn.','https://images.unsplash.com/photo-1540202404-a2f29016b523?auto=format&fit=crop&w=1400&q=85','Tùy trải nghiệm','Cả ngày','approved',1,NOW()),
(9,29,1,'Chợ Bến Thành','cho-ben-thanh',6,'Phường Bến Thành, TP. Hồ Chí Minh','Biểu tượng đô thị với ẩm thực, quà lưu niệm và nhịp sống náo nhiệt.','Chợ Bến Thành là một điểm dừng dễ tiếp cận ở trung tâm thành phố. Bên trong có nhiều gian hàng đồ thủ công, vải vóc và món ăn địa phương.\n\nHãy hỏi giá trước khi mua, ưu tiên thanh toán rõ ràng và thử một bữa sáng theo phong cách Sài Gòn.','https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1400&q=85','Miễn phí vào cửa','06:00 – 22:00','approved',0,NOW()),
(10,34,1,'Đất Mũi Cà Mau','dat-mui-ca-mau',4,'Ngọc Hiển, Cà Mau','Nơi đất liền vươn ra biển, bao quanh bởi rừng đước và phù sa.','Đất Mũi mang vẻ đẹp khoáng đạt của rừng ngập mặn và những con đường xuyên rừng. Đây là nơi nhiều du khách muốn chạm mốc cuối trời Nam.\n\nChuyến đi sẽ trọn vẹn hơn khi kết hợp trải nghiệm ẩm thực địa phương và tìm hiểu đời sống cư dân vùng ngập mặn.','https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1400&q=85','30.000đ/người','07:00 – 18:00','approved',0,NOW())
INSERT INTO articles (id,place_id,author_id,title,slug,excerpt,content,cover_image,status,is_featured,published_at) VALUES
(1,1,1,'Một ngày lênh đênh giữa kỳ quan Vịnh Hạ Long','mot-ngay-vinh-ha-long','Lịch trình gợi ý để cảm nhận trọn vẹn vẻ đẹp của Hạ Long từ bình minh đến hoàng hôn.','Buổi sáng, hãy có mặt tại bến tàu sớm để hoàn tất thủ tục và tận hưởng không khí mát dịu. Khi tàu rời bến, thành phố dần lùi lại phía sau, nhường chỗ cho những đảo đá có hình dáng kỳ thú.\n\nBuổi trưa là lúc nghỉ ngơi và thưởng thức hải sản trên tàu. Sang chiều, trải nghiệm chèo kayak đưa bạn đến gần hơn với vách núi và các áng nước kín. Hãy dành vài phút cất điện thoại để lắng nghe tiếng mái chèo và mặt nước.\n\nMột chuyến đi có trách nhiệm luôn đi cùng việc hạn chế đồ nhựa dùng một lần và không để lại rác trên vịnh.','https://images.unsplash.com/photo-1528127269322-539801943592?auto=format&fit=crop&w=1500&q=88','published',1,NOW()),
(2,2,1,'Kinh nghiệm đi thuyền Tràng An lần đầu','kinh-nghiem-di-thuyen-trang-an','Chọn tuyến, thời gian xuất phát và những vật dụng nên mang theo khi đến Tràng An.','Mỗi tuyến thuyền ở Tràng An có số hang và điểm đền khác nhau, nhưng đều kéo dài vài giờ. Nếu đi lần đầu, hãy chọn theo sức khỏe và lời tư vấn tại quầy vé.\n\nBuổi sáng thường mát, ánh sáng mềm và lượng khách dễ chịu. Mũ rộng vành, kem chống nắng, nước uống là những vật dụng nên có. Áo phao cần được mặc đúng hướng dẫn trong suốt hành trình.\n\nVào mùa lễ hội, nên tránh cuối tuần nếu bạn muốn có trải nghiệm yên tĩnh.','https://images.unsplash.com/photo-1521993117367-b7f70ccd029d?auto=format&fit=crop&w=1500&q=88','published',1,NOW()),
(3,3,1,'Chạm đỉnh Fansipan: chuẩn bị gì cho ngày săn mây?','cham-dinh-fansipan-san-may','Gợi ý trang phục, thời điểm và cách giữ sức khi lên Fansipan.','Nhiệt độ trên đỉnh có thể thấp hơn đáng kể so với trung tâm Sa Pa. Hãy mặc nhiều lớp mỏng để dễ điều chỉnh và chọn giày có độ bám tốt.\n\nNếu đi cáp treo, bạn vẫn cần leo thêm nhiều bậc thang để đến cột mốc đỉnh. Đi chậm, nghỉ đều và uống nước từng ngụm nhỏ sẽ giúp cơ thể thích nghi.\n\nBiển mây phụ thuộc thời tiết; kể cả khi trời nhiều sương, hành trình giữa núi cao vẫn là một trải nghiệm đáng nhớ.','https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1500&q=88','published',0,NOW()),
(4,4,1,'Hội An từ sớm mai đến đêm đèn lồng','hoi-an-som-mai-den-dem-den-long','Một lịch trình đi bộ chậm để nghe phố cổ kể chuyện qua từng thời khắc.','Bắt đầu ngày mới ở khu chợ khi người dân còn đang chuẩn bị hàng. Đây là lúc phố chưa đông và bạn dễ bắt gặp nhịp sống địa phương chân thật.\n\nBuổi trưa, tìm một hiên nhà râm mát, thưởng thức cao lầu rồi ghé các hội quán. Khi nắng dịu, đi dọc sông Hoài và chờ phố lên đèn.\n\nĐừng chỉ tìm góc chụp ảnh; một cuộc trò chuyện với người làm đèn lồng hay chủ quán nhỏ thường là ký ức lâu bền nhất.','https://images.unsplash.com/photo-1559592413-7cec4d0cae2b?auto=format&fit=crop&w=1500&q=88','published',1,NOW()),
(5,5,1,'Cầu Vàng trong mây: thời điểm nào đẹp nhất?','cau-vang-trong-may','Những lưu ý giúp bạn tránh đông và tận hưởng khung cảnh trên cao.','Khung giờ đầu ngày thường mang lại cơ hội tốt nhất để đi bộ thong thả trên Cầu Vàng. Tuy nhiên, sương và mây thay đổi rất nhanh nên mỗi lần ghé đều có vẻ đẹp riêng.\n\nChuẩn bị áo khoác mỏng, giày êm và kiểm tra lịch vận hành cáp treo. Không nên chen lấn ở các điểm chụp ảnh; phần giữa cầu và lối ra cũng có nhiều góc thoáng.','https://images.unsplash.com/photo-1584003564911-a7a321c84e1c?auto=format&fit=crop&w=1500&q=88','published',0,NOW()),
(6,6,1,'Nửa ngày bước qua lịch sử ở Đại Nội Huế','nua-ngay-dai-noi-hue','Lộ trình tham quan những công trình tiêu biểu trong Hoàng thành.','Từ Ngọ Môn, hành trình dẫn qua sân Đại Triều Nghi và những không gian từng là trung tâm nghi lễ. Các bảng thông tin tại điểm giúp chuyến tham quan có chiều sâu hơn.\n\nHuế nắng mạnh vào giữa ngày, vì vậy buổi sáng sớm hoặc sau 14 giờ là lựa chọn dễ chịu. Trang phục lịch sự thể hiện sự tôn trọng đối với di sản và các không gian thờ tự.','https://images.unsplash.com/photo-1570366583862-f91883984fde?auto=format&fit=crop&w=1500&q=88','published',1,NOW()),
(7,7,1,'Ra khơi ở Nha Trang: một ngày xanh trên vịnh','mot-ngay-tren-vinh-nha-trang','Kinh nghiệm chọn hoạt động biển và bảo vệ hệ sinh thái san hô.','Một chuyến đi vịnh thường bắt đầu từ sáng và ghé vài đảo trong ngày. Hãy hỏi rõ chương trình, bữa ăn và thiết bị an toàn trước khi đặt.\n\nKhi lặn ngắm san hô, giữ khoảng cách, không đứng lên rạn và không mang sinh vật biển về làm kỷ niệm. Những lựa chọn nhỏ giúp vẻ đẹp của vịnh còn mãi.','https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1500&q=88','published',0,NOW()),
(8,8,1,'Phú Quốc cho người muốn đi chậm','phu-quoc-cho-nguoi-muon-di-cham','Ba ngày cân bằng giữa biển, rừng và những buổi chiều ngắm mặt trời lặn.','Thay vì chạy theo quá nhiều điểm, hãy chia mỗi ngày cho một khu vực. Một ngày dành cho bãi biển, một ngày khám phá phía bắc và ngày còn lại thưởng thức ẩm thực địa phương.\n\nHoàng hôn bờ tây rất nổi tiếng nhưng bạn vẫn có thể tìm những đoạn bờ biển yên tĩnh. Hãy tôn trọng biển báo, không xả rác và hạn chế tác động đến hệ sinh thái.','https://images.unsplash.com/photo-1540202404-a2f29016b523?auto=format&fit=crop&w=1500&q=88','published',1,NOW()),
(9,9,1,'Ăn sáng quanh Chợ Bến Thành như người địa phương','an-sang-quanh-cho-ben-thanh','Một vòng khám phá những hương vị quen thuộc giữa trung tâm thành phố.','Buổi sáng là lúc khu chợ nhộn nhịp theo một cách rất riêng. Bạn có thể bắt đầu bằng một tô bún, thêm ly cà phê sữa đá rồi dạo quanh các gian hàng.\n\nHỏi giá và xác nhận phần ăn trước khi gọi giúp trải nghiệm thoải mái hơn. Nếu đông, hãy kiên nhẫn chia sẻ bàn như cách nhiều người địa phương vẫn làm.','https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1500&q=88','published',0,NOW()),
(10,10,1,'Về Đất Mũi nghe rừng đước thở','ve-dat-mui-nghe-rung-duoc-tho','Hành trình chạm mốc cuối trời Nam và khám phá hệ sinh thái ngập mặn.','Con đường về Đất Mũi mở dần ra cảnh quan sông nước và rừng đước. Tại khu biểu tượng, du khách có thể ngắm vùng đất bồi hướng ra biển.\n\nMột chuyến xuồng xuyên rừng mang đến góc nhìn gần gũi về hệ sinh thái ngập mặn. Hãy đi cùng người hướng dẫn địa phương và tuân thủ quy định bảo tồn.','https://images.unsplash.com/photo-1500534623283-312aade485b7?auto=format&fit=crop&w=1500&q=88','published',0,NOW())
