SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE name=VALUES(name), role=VALUES(role), status=VALUES(status);

ON DUPLICATE KEY UPDATE name=VALUES(name), description=VALUES(description);

ON DUPLICATE KEY UPDATE region_id=VALUES(region_id), name=VALUES(name), image=VALUES(image), description=VALUES(description);

ON DUPLICATE KEY UPDATE name=VALUES(name);

ON DUPLICATE KEY UPDATE name=VALUES(name), short_description=VALUES(short_description), status='approved';

ON DUPLICATE KEY UPDATE title=VALUES(title), excerpt=VALUES(excerpt), status='published';

